SAFE"},{"e":"drag-race-global-all-stars","name":"Soa de Muse","ep":5,"o":"safe","raw":"SAFE"},{"e":"drag-race-global-all-stars","name":"Soa de Muse","ep":6,"o":"elim","raw":"ELIM"},{"e":"drag-race-global-all-stars","name":"Soa de Muse","ep":9,"o":"guest","raw":"Guest"},{"e":"drag-race-global-all-stars","name":"Eva Le Queen","ep":1,"o":"guest","raw":"Guest"},{"e":"drag-race-global-all-stars","name":"Eva Le Queen","ep":2,"o":"high","raw":"TOP2"},{"e":"drag-race-global-all-stars","name":"Eva Le Queen","ep":3,"o":"safe","raw":"SAFE"},{"e":"drag-race-global-all-stars","name":"Eva Le Queen","ep":4,"o":"safe","raw":"SAFE"},{"e":"drag-race-global-all-stars","name":"Eva Le Queen","ep":5,"o":"elim","raw":"ELIM"},{"e":"drag-race-global-all-stars","name":"Eva Le Queen","ep":9,"o":"guest","raw":"Guest"},{"e":"drag-race-global-all-stars","name":"Eva Le Queen","ep":11,"o":"bottom","raw":"LOSS"},{"e":"drag-race-global-all-stars","name":"Eva Le Queen","ep":12,"o":"guest","raw":"Guest"},{"e":"drag-race-global-all-stars","name":"Miranda Lebrão","ep":1,"o":"safe","raw":"SAFE"},{"e":"drag-race-global-all-stars","name":"Miranda Lebrão","ep":2,"o":"guest","raw":"Guest"},{"e":"drag-race-global-all-stars","name":"Miranda Lebrão","ep":3,"o":"safe","raw":"SAFE"},{"e":"drag-race-global-all-stars","name":"Miranda Lebrão","ep":4,"o":"elim","raw":"ELIM"},{"e":"drag-race-global-all-stars","name":"Miranda Lebrão","ep":9,"o":"guest","raw":"Guest"},{"e":"drag-race-global-all-stars","name":"Miranda Lebrão","ep":11,"o":"bottom","raw":"LOSS"},{"e":"drag-race-global-all-stars","name":"Miranda Lebrão","ep":12,"o":"guest","raw":"Guest"},{"e":"drag-race-global-all-stars","name":"Athena Likis","ep":1,"o":"safe","raw":"SAFE"},{"e":"drag-race-global-all-stars","name":"Athena Likis","ep":2,"o":"guest","raw":"Guest"},{"e":"drag-race-global-all-stars","name":"Athena Likis","ep":3,"o":"elim","raw":"ELIM"},{"e":"drag-race-global-all-stars","name":"Athena Likis","ep":9,"o":"guest","raw":"Guest"},{"e":"drag-race-global-all-stars","name":"Athena Likis","ep":11,"o":"bottom","raw":"LOSS"},{"e":"drag-race-global-all-stars","name":"Athena Likis","ep":12,"o":"guest","raw":"Guest"}]$RES$::jsonb) r
  join public.competition_editions ed on ed.slug = r->>'e'
  join public.competition_entrants ce
    on ce.edition_id = ed.id and lower(ce.stage_name) = lower(r->>'name')
  join public.competition_episodes ep
    on ep.edition_id = ed.id and ep.episode_number = (r->>'ep')::int
on conflict (entrant_id, episode_id) do update
  set outcome = excluded.outcome, outcome_raw = excluded.outcome_raw;

do $verify$
declare v_n int; v_bad int;
begin
  select count(*) into v_n from public.competition_episode_results;
  -- A TIGHT floor. Every result should land: its entrant is inserted from the
  -- same season object and its episode is now guaranteed to exist (the episode
  -- list is the union of the episode table and the grid).
  --
  -- This was 0.7 and that was useless — it happily passed while the join was
  -- silently dropping 1,718 rows (23% of the grid) because the episode row did
  -- not exist. A floor loose enough to absorb the bug it exists to catch is not
  -- a guard. 0.98 leaves room for a single malformed season, nothing more.
  if v_n < 7229 then
    raise exception 'episode results: expected >= %, got % — the join is dropping rows',
      7229, v_n;
  end if;

  -- Nothing may carry an outcome outside the ladder+guest vocabulary.
  select count(*) into v_bad from public.competition_episode_results
   where outcome not in ('win','high','safe','low','bottom','elim','guest');
  if v_bad <> 0 then raise exception '% result(s) with an unknown outcome', v_bad; end if;

  raise notice 'competition results: % rows', v_n;
end
$verify$;
